-- Alianza BKO + CAUCE y nuevos clientes (13-11-2026). Ejecutar una vez en el editor SQL de Supabase (proyecto BKO).
-- Textos según la carta de CAUCE «Sitio bko.cl: cómo presentar la alianza BKO + CAUCE» (12-11-2026).
-- Reemplaza solo las frases indicadas; conserva el resto de lo editado desde el CMS.
begin;

-- CAUCE: párrafo inicial y redacción general de las etapas 04 y 07.
update public.bko_content set data = jsonb_set(data, '{description}', to_jsonb('CAUCE Gestión Integral, fundada por Luis Miranda Chavarría, trabaja en alianza con BKO para resolver la cobranza de empresas del norte de Chile. CAUCE levanta y ordena la información de cada deuda (facturas, pagos, correspondencia y antecedentes del deudor) y la entrega lista para que el equipo jurídico de BKO evalúe la causa y conduzca el cobro.'::text))
where id = 'cauce' and data->>'description' like 'Creado por Luis Miranda%';
update public.bko_content set data = replace(replace(replace(replace(replace(replace(replace(replace(data::text, 'Ingeniero Civil | Creador de CAUCE Gestión Integral', 'Ingeniero Civil | Fundador de CAUCE Gestión Integral'), 'ingeniero civil y creador de CAUCE Gestión Integral', 'ingeniero civil y fundador de CAUCE Gestión Integral'), 'Los expedientes elaborados por CAUCE reflejan un trabajo que integra', 'Los expedientes elaborados por CAUCE integran'), 'En los antecedentes analizados se individualizan pagos por', 'En cada cartera se individualizan los pagos por'), 'El informe de traspaso examinado contiene una sección específica dedicada a información que no estaba disponible en la carpeta', 'Cada informe de traspaso contiene una sección dedicada a la información que no está disponible en la carpeta'), 'Estefanía es asistente contable de BKO y está a cargo de la gestión de CAUCE Gestión Integral, el sistema de la oficina para organizar y dar seguimiento documental a las carteras de cobranza.', 'Estefanía es asistente contable de BKO y apoya la coordinación de los casos de cobranza que prepara CAUCE.'), 'Asistente contable | Gestión de CAUCE', 'Asistente contable | Coordinación de cobranza'), 'Gestión de CAUCE', 'Coordinación de casos de cobranza')::jsonb
where id in ('cauce','luis-miranda-chavarria','estefania-benitez-garcia');

-- Nuevos clientes con su logotipo: Ibanez Soluciones, SISA y Capitalfin.
