insert into public.bko_clients(slug,name,original_name,website_url,website_original,website_verified,logo_local_path,logo_storage_path,logo_verified,logo_authorized,logo_source,logo_source_original,logo_status_original,verification_status,observations,sector,sector_source,description,sort_order,active,published,featured,relation_authorized,authorization_reference,logo_authorization_reference,original_row,logo_width,logo_height,logo_background) values('sisa','SISA Ingeniería, Arriendos y Obras Civiles','SISA Ingeniería, Arriendos y Obras Civiles','','',false,'assets/clientes/sisa.png','',true,true,'Entregado por el responsable del sitio (clientes/Logo SisA.png)','','Logotipo entregado por el responsable del sitio','verified','Cliente agregado por instrucción del responsable del sitio (13-11-2026).','construccion','Logotipo entregado por el responsable del sitio','Ingeniería, arriendos y obras civiles.',280,true,true,true,true,'Instrucción del responsable del sitio, 13-11-2026: agregar SISA Ingeniería, Arriendos y Obras Civiles a la sección de empresas con su logotipo.','Instrucción del responsable del sitio, 13-11-2026, de mostrar el logotipo de SISA Ingeniería, Arriendos y Obras Civiles.','Logo SisA, nuevo cliente',540,606,'white') on conflict(slug) do nothing;
